solution.Words.java:
import java.util.*;
import java.util.stream.*;

public final class Words {
    public static TreeMap<Integer, List<String>> byLength(List<String> words) {
        return words.stream().collect(Collectors.groupingBy(String::length, TreeMap::new,
                Collectors.collectingAndThen(Collectors.toCollection(TreeSet::new), ArrayList::new)));
    }

    public static Map<Character, Long> firstLetters(List<String> words) {
        return words.stream()
                .filter(w -> !w.isEmpty())
                .collect(Collectors.groupingBy(w -> Character.toLowerCase(w.charAt(0)), TreeMap::new, Collectors.counting()));
    }
}

unitTests:
test("by length, sorted, no duplicates", () -> {
    var r = Words.byLength(List.of("pear", "fig", "kiwi", "apple", "fig", "date"));
    checkEq(r.toString(), "{3=[fig], 4=[date, kiwi, pear], 5=[apple]}");
});

test("first letters", () -> {
    var r = Words.firstLetters(List.of("Apple", "avocado", "", "banana", "Blueberry", "cherry"));
    checkEq(r.toString(), "{a=2, b=2, c=1}");
});

test("empty input", () -> {
    checkEq(Words.byLength(List.of()).size(), 0);
    checkEq(Words.firstLetters(List.of()).size(), 0);
});

